# Every system app loses its build-time odex here (the boot image is rebuilt on device, see regen_boot_profile.sh), so
# after a flash each one is dexopted on device. With pm.dexopt.boot-after-ota=verify (source default) a package only
# gets compiled when background dexopt runs (idle + charging) and only for the methods of a runtime profile collected
# meanwhile - i.e. the ROM feels slow for days after each update. speed-profile at the post-flash boot compiles every
# package that ships a profile (Samsung's .prof files regenerated by regen_app_profiles.sh, the target's own text
# profiles, Play-delivered .dm) right away; packages without a profile stay verify-only, so the boot cost is bounded.
SET_PROP "system" "pm.dexopt.boot-after-ota" "speed-profile"
SET_PROP "system" "pm.dexopt.first-boot" "speed-profile"
SET_PROP "system" "pm.dexopt.post-boot" "verify"

# The source enables ART's userfaultfd GC; the 5.4 kernel has no userfaultfd support, odrefresh logs
# "Userfaultfd GC check failed ... kernel_supports_uffd: false" on every run and falls back to the CC collector.
# Match the target (A52s stock has it off) so the runtime and odrefresh agree from the start.
SET_PROP "product" "ro.dalvik.vm.enable_uffd_gc" "false"

# Performance profile "Light" (Settings > Device care > Performance profile) acquires the vendor hyper hint
# LOW_HEAT_MODE_HINT (ID 900), whose CPUMaxFreq "90#" is a position in Samsung's unified /sys/power/cpufreq_table, not a
# percentage: HYPER-HAL applies 2208000 (measured; 86# gave the same), barely below Standard's 2.4 GHz. The HAL also
# takes absolute kHz values, so cap at 2054400 (big cluster 2.05 GHz step; prime settles on 2035200), ~2.0 GHz, for the
# hint and its app-start variant (APP_START_LOW_HEAT, ID 901). GPU and DDR caps are left alone.
HYPER_CFG="$WORK_DIR/vendor/etc/hyper/config_vendor.json"
[ -f "$HYPER_CFG" ] || ABORT "perf_tuning: /vendor/etc/hyper/config_vendor.json not found"
python3 - "$HYPER_CFG" << 'PYEOF' || ABORT "Failed to lower the Light performance profile CPU cap"
import re, sys
p = sys.argv[1]; s = open(p).read()
n = 0
def fix(m):
    global n
    block = m.group(0)
    new, k = re.subn(r'("Resource" : "CPUMaxFreq",\s*"Value" : ")90#(")', r'\g<1>2054400\2', block, count=1)
    n += k
    return new
s = re.sub(r'"Hint": "(?:LOW_HEAT_MODE_HINT|APP_START_LOW_HEAT)",.*?\]\s*\}', fix, s, flags=re.S)
if n != 2:
    sys.exit("expected 2 CPUMaxFreq 90# entries in the LOW_HEAT hints, patched %d" % n)
open(p, "w").write(s)
PYEOF
LOG "- Light performance profile: CPU cap 2208000 -> 2054400 kHz (~2.0 GHz)"
unset HYPER_CFG
